window.OxidPayPal = {
    sdkLoaded: false,
    onSDKLoaded: function () {
        const PayPalSDKLoadedEvent = new CustomEvent('PayPalSDKLoadedEvent', {
            bubbles: false,
            cancelable: false
        });

        window.dispatchEvent(PayPalSDKLoadedEvent);
        this.sdkLoaded = true;
    },
    isSDKLoaded: function () {
        return this.sdkLoaded;
    }
};

// After receiving PAYER_ACTION_REQUIRED from PayPal

window.OxidPayPalGooglePay3DS = {
    handle: async (paypalOrderResponse) => {
        // Create new payment data request with 3DS parameters
        const paymentDataRequest = await window.OxidPayPalGooglePay.getGooglePaymentDataRequest();
        const threeDSPaymentDataRequest = {
            ...paymentDataRequest,
            paymentData: {
                tokenizationData: {
                    type: 'PAYMENT_GATEWAY',
                    token: paypalOrderResponse.id // Original PayPal order ID
                },
                // 3DS specific parameters
                threeDSData: {
                    authenticationParameters: {
                        threeDSRequestData: {
                            threeDSServerTransID: generateTransactionId(),
                            challengeWindowSize: "03", // Full screen
                            messageCategory: "PAYMENT_AUTHENTICATION"
                        }
                    }
                }
            }
        };

        try {
            // This triggers the 3DS popup
            const paymentData = await paymentClient.loadPaymentData(threeDSPaymentDataRequest);

            // After successful 3DS authentication
            // Update PayPal order with new payment token
            const updateOrderResponse = await fetch(`/v2/checkout/orders/${paypalOrderResponse.id}`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify([{
                    op: 'replace',
                    path: '/payment_source/google_pay/card/authentication_result',
                    value: {
                        liability_shift: "POSSIBLE",
                        three_d_secure: {
                            authentication_status: "Y",
                            enrollment_status: "Y"
                        }
                    }
                }])
            });

            // Finally capture the order
            if (updateOrderResponse.ok) {
                const captureResponse = await fetch(`/v2/checkout/orders/${paypalOrderResponse.id}/capture`, {
                    method: 'POST'
                });
                return captureResponse;
            }
        } catch (error) {
            // Handle 3DS or payment errors
            console.error('3DS Authentication failed:', error);
            throw error;
        }
    }
};

(function () {
    'use strict';

    function OxidPayPalHateoasLinks() {
    }
    /**
     * @typedef {Object} Link
     * @property {string} rel - The relation type.
     * @property {string} href - The link URL.
     */

    /**
     * Process an array of links and return the aprove-link
     * @param {Link[]} links - An array of link objects.
     *
     * @returns {string|null}
     */
    OxidPayPalHateoasLinks.prototype.getApproveLink = function (links) {
        return this.getLinkByKeyword(links, 'approve');
    };

    /**
     * Process an array of links and return the payer-action-link
     * @param {Link[]} links - An array of link objects.
     *
     * @returns {string|null}
     */
    OxidPayPalHateoasLinks.prototype.getPayerActionLink = function (links) {
        return this.getLinkByKeyword(links, 'payer-action');
    };

    /**
     * Process an array of links.
     * @param {Link[]} links - An array of link objects.
     *
     * @returns {string|null}
     */
    OxidPayPalHateoasLinks.prototype.getLinkByKeyword = function (links, keyword) {
        const hateoasLink = links.find(link => link.rel === keyword);

        if (hateoasLink) {
            return hateoasLink.href;
        }

        return null;
    };

    window.OxidPayPalHateoasLinks = OxidPayPalHateoasLinks;
})();

function deselectRadioButtons(selector) {
    const radioButtons = document.querySelectorAll(selector);
    radioButtons.forEach(item => {
        item.checked = false;
    });
}

/**
 * Helper function to get the payment submit button
 * @returns {Element|null} The payment submit button element or null if not found
 */
function getPaymentSubmitButton() {

    const smartyButton = document.getElementById('paymentNextStepBottom');
    if (smartyButton) {
        return smartyButton;
    }

    const apexButton = document.querySelector('button[onclick*="document.getElementById(\'payment\').submit()"]');
    if (apexButton) {
        return apexButton;
    }

    return null;
}

function registerClickListenerForPaymentMethodsRadioButtons() {
    const paymentMethodsRadioButtons = document.getElementById('payment').querySelectorAll('[type="radio"]');
    paymentMethodsRadioButtons.forEach(function(paymentMethod) {
        paymentMethod.onclick = function() {
            const paypalVaultCheckoutButton = document.getElementById("paypalVaultCheckoutButton");
            if (paypalVaultCheckoutButton) {
                document.getElementById("paypalVaultCheckoutButton").disabled = true;
            }
            if (paymentMethod.checked) {
                getPaymentSubmitButton().disabled = false;
                deselectRadioButtons(".vaulting_paymentsource");
            }
        };
    });
}

function registerClickListenerForSavedVaultRadioButtons() {
    const vaultingPaymentSourceRadioButtons = document.querySelectorAll(".vaulting_paymentsource");
    if (vaultingPaymentSourceRadioButtons && vaultingPaymentSourceRadioButtons.length > 0) {
        vaultingPaymentSourceRadioButtons.forEach(function(paymentsource) {
            paymentsource.onclick = function() {
                if (paymentsource.checked) {
                    document.getElementById("paypalVaultCheckoutButton").disabled = false;
                    getPaymentSubmitButton().disabled = true;
                    deselectRadioButtons('#payment [type="radio"]');
                }
            };
        });
    }
}

function registerClickListenerForTheVaultCheckoutButton() {
    const paypalVaultCheckoutButton = document.getElementById("paypalVaultCheckoutButton");
    if (paypalVaultCheckoutButton) {
        paypalVaultCheckoutButton.onclick = function() {
            const vaultingPaymentSourceRadioButtons = document.querySelectorAll(".vaulting_paymentsource");
            if (vaultingPaymentSourceRadioButtons && vaultingPaymentSourceRadioButtons.length > 0) {
                vaultingPaymentSourceRadioButtons.forEach(function(paymentsource) {
                    if (paymentsource.checked) {
                        const paymenttype = paymentsource.dataset.paymenttype;
                        const paymentId = paymenttype === 'card' ? "oscpaypal_acdc" : "oscpaypal";

                        let vaultedPaymentInput = document.createElement("input");
                        vaultedPaymentInput.type = "hidden";
                        vaultedPaymentInput.name = "vaultingpaymentsource";
                        vaultedPaymentInput.value = paymentsource.dataset.tokenId;
                        document.getElementById("payment").appendChild(vaultedPaymentInput);

                        let paymentIdInput = document.createElement("input");
                        paymentIdInput.type = "hidden";
                        paymentIdInput.name = "paymentid";
                        paymentIdInput.value = paymentId;
                        document.getElementById("payment").appendChild(paymentIdInput);

                        let nextPaymentStepButton = getPaymentSubmitButton();
                        nextPaymentStepButton.disabled = false;
                        nextPaymentStepButton.click();
                        nextPaymentStepButton.disabled = true;
                    }
                });
            }
        };
    }
}

document.addEventListener("DOMContentLoaded", function() {
    const paymentIdForm = document.getElementById('payment');
    if (null === paymentIdForm) {
        return;
    }

    registerClickListenerForPaymentMethodsRadioButtons();
    registerClickListenerForSavedVaultRadioButtons();
    registerClickListenerForTheVaultCheckoutButton();
});

(function () {
    let PayPalPaymentControllerBase = function (config) {
        this.config = Object.assign(PayPalPaymentControllerConfig, typeof config === 'object' ? config : {});

        this.currentOrderDefaults = {
            shop: null,
            paypal: null,
            vaultPayment: false
        };
        this.currentOrder = null;
        this.currentError = null;
        this.reactOnPayPalOverlayClosed = false;

        this.getPaymentData = function () {
            let purchaseUnits = {
                intent: PayPalPayment.getConfigValue('captureStrategy'),
                purchase_units: [
                    {...this.config.purchaseUnits}
                ]
            };

            purchaseUnits.payment_source = this.getPaymentSource();

            return purchaseUnits;
        };

        // Common initialization methods
        this.resetCurrentOrder = function () {
            this.currentOrder = {...this.currentOrderDefaults};
        };

        this.setCreatePayPalOrderResponse = function (response) {
            this.currentOrder.paypal = response;
        };

        this.setShopOrderData = async function (response, orderType) {
            if (null !== this.currentOrder.shop) {
                await PayPalPayment.cancelOrder().then(function (data) {
                    PayPalPayment.resetCurrentOrder();
                });
            }

            PayPalPayment.currentOrder[orderType] = response;
            PayPalPayment.config.purchaseUnits.custom_id = response.customId;
        };

        this.getCurrentOrderData = function (name, orderType) {
            if (null == this.currentOrder[orderType]) {
                console.warn('No current order.');
                return null;
            }

            if (undefined === this.currentOrder[orderType][name]) {
                console.warn('Current order do not have detail named ' + name + '.');
                return null;
            }

            return this.currentOrder[orderType][name];
        };

        this.getCurrentOrderOxid = function () {
            return this.getCurrentOrderData('shopOrderId', 'shop');
        };

        this.getCurrentPayPalOrderId = function () {
            // check if part: this.getCurrentOrderData('orderID', 'paypal') is needed, maybe in ACDC
            const payPalOrderId =
                this.getCurrentOrderData('orderID', 'paypal') || this.getCurrentOrderData('id', 'paypal');

            return payPalOrderId || null;
        };

        this.getConfigValue = function (name) {
            return undefined !== this.config[name] ? this.config[name] : null;
        };

        // Common event handlers
        this.onShopOrderCreated = function (data) {
            PayPalPayment.setShopOrderData(data.detail, 'shop');
        };

        this.onPayPalOrderCreated = function (data) {
            PayPalPayment.setCreatePayPalOrderResponse(data.detail);
        };

        this.vaultingSettingSwitch = function (e) {
            PayPalPayment.currentOrder.vaultPayment = e.currentTarget.checked;
        };

        // Common order processing methods
        this.patchOrder = async function (details) {
            const shopOrderId = PayPalPayment.getCurrentOrderOxid();
            const payPalOrderId = PayPalPayment.getCurrentPayPalOrderId();

            if (!shopOrderId) {
                console.error('Missing shop order ID for order patching');
                return { error: 'Missing shop order ID' };
            }

            if (!payPalOrderId) {
                console.error('Missing PayPal order ID for order patching');
                return { error: 'Missing PayPal order ID' };
            }

            if (!PayPalPayment.currentOrder || typeof PayPalPayment.currentOrder.vaultPayment === 'undefined') {
                console.error('Missing vault payment information for order patching');
                return { error: 'Missing vault payment information' };
            }

            return await PayPalPayment.backendRequest('shopOrderPatchingUrl', {}, {
                'shopOrderId': shopOrderId,
                'payPalOrderId': payPalOrderId,
                'vaultPayment': PayPalPayment.currentOrder.vaultPayment
            });
        };

        this.vaultPayment = async function (details) {
            try {
                if (details.payment_source.paypal) {
                    const vaultToken = details.payment_source.paypal.attributes.vault.id;

                    if (!vaultToken) {
                        console.warn('No PayPal vault token found in order details');
                        return;
                    }
debugger
                    const result = await PayPalPayment.backendRequest('updateOxUserWithPayPalCustomerIdUrl', {}, {
                        'payPalCustomerId': details.payment_source.paypal.attributes.vault.customer.id,
                    });

                    if (result.status !== 'success') {
                        console.error('Failed to store PayPal vault token:', result.message);
                    }
                } else if (details.payment_source.card) {
                    const cardToken = details.payment_source.card.attributes.vault.id;
                    if (!cardToken) {
                        console.warn('No card vault token found in order details');
                        return;
                    }

                    const result = await PayPalPayment.backendRequest('updateOxUserWithCardTokenUrl', {}, {
                        'cardToken': cardToken,
                        'cardDetails': details.payment_source.card
                    });

                    if (result.status !== 'success') {
                        console.error('Failed to store card vault token:', result.message);
                    }
                }
            } catch (error) {
                console.error('Error processing vault token:', error);
            }
        };

        this.afterCaptureOrder = async function (details) {
            const result = await PayPalPayment.patchOrder(details);

            if (result.error) {
                console.error('Failed to patch order:', result.error);
                PayPalPayment.handleError();
                return;
            }

            const {paypalOrderDetails} = result;

            if (paypalOrderDetails && paypalOrderDetails.payment_source) {
                await PayPalPayment.vaultPayment(paypalOrderDetails);
            }

            window.location = PayPalPayment.getConfigValue('shopThankYouPageUrl');
        };

        this.handlePaymentAuthorization = async function (details) {
            PayPalPayment.setCreatePayPalOrderResponse(details);
            const patchResult = await PayPalPayment.patchOrder(details);

            if (patchResult.error) {
                console.error('Failed to patch order:', patchResult.error);
                PayPalPayment.handleError();
                return;
            }

            const {paypalOrderDetails} = patchResult;

            if (PayPalPayment.currentOrder.vaultPayment && paypalOrderDetails && paypalOrderDetails.payment_source) {
                await PayPalPayment.vaultPayment(paypalOrderDetails);
            }

            const result = await PayPalPayment.authorizeOrder(paypalOrderDetails);

            if (result.paymentStatus === 'success' ){
                window.location = PayPalPayment.getConfigValue('shopThankYouPageUrl');
                return;
            }

            PayPalPayment.handleError();
        };

        this.authorizeOrder = async function (data) {
            const orderId = data.id || PayPalPayment.getCurrentPayPalOrderId();
            const shopOrderId = PayPalPayment.getCurrentOrderOxid();
            const paymentId = PayPalPayment.getConfigValue('paymentId');

            if (!orderId) {
                console.error('No PayPal order ID available for authorization');
                return;
            }

            try {
                const result = await PayPalPayment.backendRequest('shopOrderAuthorizeUrl', {}, {
                    'orderId': orderId,
                    'shopOrderId': shopOrderId,
                    'paymentId': paymentId
                });

                if (result.status !== 'success') {
                    console.error('Order authorization failed:', result.message);
                    PayPalPayment.handleError();
                }

                return result;
            } catch (error) {
                console.error('Error during order authorization:', error);
                PayPalPayment.handleError();
            }

            return {status: 'error'};
        };

        this.cancelOrder = async function () {
            // Don't remove the overlay, as we'll reload the page at the end.
            // During this time, no one should be able to click anything.
            // PayPalPayment.removeSubmitButtonOverlay();

            let shopOrderId = PayPalPayment.getCurrentOrderOxid();
            if (null == shopOrderId) {
                return;
            }

            await PayPalPayment.backendRequest('shopOrderCancelUrl', {}, {
                'shopOrderId': PayPalPayment.getCurrentOrderOxid()
            });

            PayPalPayment.resetCurrentOrder();
            window.location.reload();
        };

        this.handleError = async function (data) {
            if ('undefined' !== data && data instanceof Error){
                PayPalPayment.showErrorMessage(PayPalI18n.OSC_PAYPAL_AUTHORIZATION_DENIED_ERROR);
            }

            let shopOrderId = PayPalPayment.getCurrentOrderOxid();
            if (null == shopOrderId) {
                return;
            }

            await PayPalPayment.cancelOrder();
        };

        // Common backend request method
        this.backendRequest = async function (urlSlug, headers, body) {
            let response;
            let result = {status: 'pending'};

            try {
                body.trackingId = PayPalPayment.getConfigValue('trackingId');
                response = await fetch(PayPalPayment.getConfigValue(urlSlug), {
                    method: 'post',
                    headers: Object.assign({
                        'content-type': 'application/json',
                    }, headers),
                    body: JSON.stringify(body)
                });

                result = await response.json();
            } catch (error) {
                console.error('Operation failed:', error);
                result = {
                    status: 'error',
                    error: error.message
                };
                // Ensure order cancellation if operation fails
                await PayPalPayment.handleError();
                return result;
            }

            console.log(result.status, result.message, result.data);
            await new Promise(resolve => setTimeout(resolve, 5000));
            if (result.status !== 'success') {
                PayPalPayment.handleError();
            }

            return result;
        };

        this.buttonControl = function (property, value) {
            const submitButton = document.querySelector(PayPalPayment.config.buttonSelector);
            if (undefined !== submitButton[property]) {
                submitButton[property] = value;
            }
        };

        this.paypalOverlayWatcher = function () {
            const overlayClosedEvent = new Event('paypalOverlayClosed');

            // Options for the observer (which mutations to observe)
            const config = {childList: true, subtree: true};

            // Create an observer instance
            const observer = new MutationObserver(function (mutations) {
                mutations.forEach(function (mutation) {
                    let addedNodes = mutation.addedNodes;

                    addedNodes.forEach(function (node) {
                        if (node.nodeType === Node.ELEMENT_NODE) {

                            if (node.id.startsWith('paypal-overlay-uid_')) {
                                const overlayObserver = new MutationObserver(function (ovMutations, ovObserver) {
                                    ovMutations.forEach(function (ovMutation) {
                                        ovMutation.removedNodes.forEach(function (removedNode) {
                                            if (removedNode === node ||
                                                (removedNode.contains && removedNode.contains(node))) {


                                                document.dispatchEvent(overlayClosedEvent);
                                                ovObserver.disconnect();
                                            }
                                        });
                                    });
                                });

                                // Start observing the parent of the iframe for removal
                                if (node.parentNode) {
                                    overlayObserver.observe(node.parentNode, {childList: true});
                                }
                            }
                        }
                    });
                });
            });
            observer.observe(document.body, config);

            PayPalPayment.reactOnPayPalOverlayClosed = true;

            return observer;
        };

        this.initializeAcceptPaymentButton = function () {
            const submitButton = document.querySelector(PayPalPayment.config.buttonSelector);
            submitButton.addEventListener('click', function (e) {
                e.stopPropagation();
                e.preventDefault();
                PayPalPayment.addSubmitButtonOverlay();

                if (PayPalPayment.config.vaultedPaymentSource) {
                    PayPalPayment.createOrder();
                }
            });
        };

        // Add a non-clickable overlay to a DOM element
        // If an overlay already exists on the element, returns the existing overlay instead of creating a new one
        this.addOverlay = function (element) {
            if (!element) {
                console.warn('No element provided to add overlay');
                return null;
            }

            // Check if overlay already exists
            const existingOverlay = element.querySelector('.paypal-element-overlay');
            if (existingOverlay) {
                console.log('Overlay already exists, returning existing overlay');
                return existingOverlay;
            }

            // Create overlay element
            const overlay = document.createElement('div');
            overlay.className = 'paypal-element-overlay';

            // Set overlay styles
            overlay.style.position = 'absolute';
            overlay.style.top = '0';
            overlay.style.left = '0';
            overlay.style.width = '100%';
            overlay.style.height = '100%';
            overlay.style.backgroundColor = 'rgba(255, 255, 255, 0.5)';
            overlay.style.zIndex = '1000';
            overlay.style.cursor = 'not-allowed';

            // Make sure the target element has position relative or absolute
            const elementPosition = window.getComputedStyle(element).position;
            const validPositions = ['relative', 'absolute', 'fixed', 'sticky'];

            if (!validPositions.includes(elementPosition)) {
                element.style.position = 'relative';
            }

            // Add overlay to the element
            element.appendChild(overlay);

            return overlay;
        };

        // Remove overlay(s) from a DOM element
        this.removeOverlay = function (element) {
            if (!element) {
                console.warn('No element provided to remove overlay from');
                return false;
            }

            // Get the parent of the element
            const parent = element.parentNode;
            if (!parent) {
                console.warn('Element has no parent node');
                return false;
            }

            // Find all overlays within the parent element
            const overlays = parent.querySelectorAll('.paypal-element-overlay');
            if (!overlays || overlays.length === 0) {
                console.warn('No overlays found in the parent of the provided element');
                return false;
            }

            // Remove all overlay
            overlays.forEach(overlay => {
                parent.removeChild(overlay);
            });

            return true;
        };

        this.removeSubmitButtonOverlay = function() {
            const submitButton = document.getElementById(
                PayPalPayment.getConfigValue('buttonSelector').split('#').reverse()[0]
            );
            PayPalPayment.removeOverlay(submitButton);
        };

        this.addSubmitButtonOverlay = function() {
            const submitButton = document.getElementById(
                PayPalPayment.getConfigValue('buttonSelector').split('#').reverse()[0]
            );
            PayPalPayment.addOverlay(submitButton.parentElement);
        };

        this.showErrorMessage = function (message, className) {
            if(message.length === 0) {
                message = PayPalI18n.OSC_PAYPAL_UNKNOWN_ERROR;
            }

            className = className || '';
            const panelBody = document.querySelector("#orderPayment").parentElement;

            // Remove existing error if present
            this.removeErrorMessage(className);
            PayPalPayment.currentError = message;
            // Create and display a new error message
            const errorMessage = document.createElement("div");
            errorMessage.className = "error-message alert alert-danger " + className;
            errorMessage.textContent = message;

            panelBody.prepend(errorMessage);

            errorMessage.scrollIntoView({
                behavior: 'smooth'
            });
        };

        this.removeErrorMessage = function (className) {
            className = className || '';
            const panelBody = document.querySelector("#orderPayment").parentElement;
            if (panelBody) {
                const existingError = panelBody.querySelector(".error-message" + (className ? '.' + className : ''));
                if (existingError) {
                    existingError.remove();
                }
            }
            PayPalPayment.currentError = null;
        };

        // Common initialization
        this.init = function () {
            this.resetCurrentOrder();

            const savePaymentChackbox = document.getElementById('oscPayPalVaultPaymentCheckbox');
            if (savePaymentChackbox) {
                savePaymentChackbox.onclick = this.vaultingSettingSwitch;
            }

            document.addEventListener('shopOrderCreated', this.onShopOrderCreated);
            document.addEventListener('payPalOrderCreated', this.onPayPalOrderCreated);

            document.dispatchEvent(new CustomEvent('PayPalPaymentControllerInitialized', new Object({detail: this})));

            return this;
        };

        return this;
    };

    // Make the base class available
    window.PayPalPaymentControllerBase = PayPalPaymentControllerBase;
})();

(function () {
    let PayPalStandardPaymentController = function (config) {
        // Inherit from base controller
        PayPalPaymentControllerBase.call(this, config);

        // PayPal-specific payment source configuration
        this.getPaymentSource = function () {
            debugger
            let paymentSource = {
                paypal: {
                    experience_context: {
                        shipping_preference: "SET_PROVIDED_ADDRESS",
                        return_url: PayPalPayment.getConfigValue("updateOxUserWithPayPalCustomerIdUrl"),
                        cancel_url: PayPalPayment.getConfigValue("shopOrderCancelUrl")
                    }
                }
            };

            const customerId = PayPalPayment.getConfigValue('customerId');
            if (customerId) {
                paymentSource.paypal.attributes = {
                    customer: {
                        id: customerId
                    }
                };
            }

            return PayPalPayment.currentOrder.vaultPayment ?
                PayPalPayment.modifyPaymentSourceForVaulting(paymentSource) :
                paymentSource;
        };

        this.modifyPaymentSourceForVaulting = function (paymentSource) {
            paymentSource.paypal.attributes = Object.assign(paymentSource.paypal.attributes || {},
                {
                    vault: {
                        store_in_vault: "ON_SUCCESS",
                        usage_type: "MERCHANT",
                        customer_type: "CONSUMER",
                        permit_multiple_payment_tokens: true
                    }
                }
            );

            return paymentSource;
        };

        // PayPal-specific order creation
        this.createOrder = async function (data, actions) {
            PayPalPayment.addSubmitButtonOverlay();
            PayPalPayment.paypalOverlayWatcher();

            // Create shop order first
            let shopOrderCreateResult = await PayPalPayment.backendRequest('shopOrderCreateUrl', {}, {
                'deliveryAddressId': PayPalPayment.getConfigValue('deliveryAddressId'),
                'paymentId': PayPalPayment.getConfigValue('paymentId')
            });

            document.dispatchEvent(new CustomEvent('shopOrderCreated', new Object({detail: {...shopOrderCreateResult}})));

            // Create PayPal order
            let payPalOrderCreateResult = await PayPalPayment.backendRequest('payPalOrderCreateUrl', {}, {
                'shopOrderId': shopOrderCreateResult.shopOrderId,
                'vaultPayment': PayPalPayment.currentOrder.vaultPayment,
                'useVaultedPayment': PayPalPayment.config.vaultedPaymentSource,
                'deliveryAddressId': PayPalPayment.getConfigValue('deliveryAddressId')
            });

            document.dispatchEvent(new CustomEvent('payPalOrderCreated', new Object({detail: {...payPalOrderCreateResult.payPalOrder}})));

            if (payPalOrderCreateResult.status !== 'success') {
                throw new Error('PayPal order creation failed: ' + payPalOrderCreateResult.message);
            }

            //if the vaulted payment source is used, go to finalize payment
            if (null !== PayPalPayment.config.vaultedPaymentSource && payPalOrderCreateResult.payPalOrder.status === 'COMPLETED') {
                PayPalPayment.afterCaptureOrder();
            }

            return payPalOrderCreateResult.payPalOrder.id;
        };

        this.captureOrder = async function (data, actions) {
            //if we managed to get at this stage, closing the overlay not suppose to be watched anymore
            PayPalPayment.reactOnPayPalOverlayClosed = false;
            let result = await PayPalPayment.backendRequest('shopOrderCaptureUrl', {}, {
                'orderId': data.orderID,
                'paymentId': PayPalPayment.getConfigValue('paymentId')
            });
debugger
            if (result.paymentStatus === 'success') {
                PayPalPayment.afterCaptureOrder();
            }
        };

        // PayPal-specific button settings
        this.getPayButtonSettings = function () {
            const buttonSettings = {
                createOrder: PayPalPayment.createOrder,
                onApprove: PayPalPayment.handlePaymentAuthorization,
                onCancel: PayPalPayment.cancelOrder,
                onError: PayPalPayment.handleError
            };

            if (PayPalPayment.config.captureStrategy === 'CAPTURE') {
                buttonSettings.onApprove = PayPalPayment.captureOrder;
            }

            return buttonSettings;
        };

        // PayPal-specific button rendering
        this.renderButton = function (style) {
            const vaultedPaymentSource = null !== PayPalPayment.getConfigValue('vaultedPaymentSource');
            if (vaultedPaymentSource) {
                this.initializeAcceptPaymentButton();
            } else {
                const buttonSettings = Object.assign(
                    PayPalPayment.getPayButtonSettings(),
                    {
                        style: typeof style == 'object' ? style : {}
                    }
                );
                let button = paypal.Buttons(buttonSettings);

                if (button.isEligible()) {
                    button.render(PayPalPayment.getConfigValue('buttonSelector'));
                }
            }
        };

        return this.init();
    };

    window.addEventListener('load', function () {
        if (typeof PayPalPaymentControllerConfig === 'object' &&
            PayPalPaymentControllerConfig.paymentId === 'oscpaypal') {
            window.PayPalPayment = new PayPalStandardPaymentController();

            window.PayPalPayment.renderButton(typeof PayPalButtonStyle === 'object' ? PayPalButtonStyle : {});
        }
    });
})();

(function () {
    let PayPalACDCPaymentController = function (config) {
        // Inherit from base controller
        PayPalPaymentControllerBase.call(this, config);

        this.cardFieldsState =
            {
                fields: {
                    "cardNameField": { isValid: null },
                    "cardNumberField": { isValid: null },
                    "cardExpiryField": { isValid: null },
                    "cardCvvField": { isValid: null }
                }
            };

        this.createOrder = async function (data, actions) {
            PayPalPayment.reactOnPayPalOverlayClosed = false;
            let result = await PayPalPayment.backendRequest('shopOrderCreateUrl', {}, {
                'deliveryAddressId': PayPalPayment.getConfigValue('deliveryAddressId'),
                'vaultPayment': PayPalPayment.currentOrder.vaultPayment,
                'paymentId': PayPalPayment.getConfigValue('paymentId')
            });

            if (result.status === 'error' ){
                PayPalPayment.showErrorMessage(result.message);
                PayPalPayment.handleError(result.message);

                return false;
            }

            document.dispatchEvent(new CustomEvent('shopOrderCreated', new Object({detail: {...result.shopOrder}})));
            document.dispatchEvent(new CustomEvent('payPalOrderCreated', new Object({detail: {...result.payPalOrder}})));
            let shopOrderId = result.shopOrder.shopOrderId;

            //vaulted payment source
            if (result.payPalOrder.status === 'COMPLETED' ){
                let result = await PayPalPayment.backendRequest('shopOrderCompleteUrl', {}, {
                    'orderId': shopOrderId
                });
                if ('success' !== result.status) {
                    return false;
                }

                window.location = PayPalPayment.getConfigValue('shopThankYouPageUrl');
            }

            if (result.payPalOrder.status === 'PAYER_ACTION_REQUIRED' || result.payPalOrder.status === 'APPROVED' ){
                for (const i in result.payPalOrder.links) {
                    if (result.payPalOrder.links[i].rel === 'payer-action'){
                        window.location = result.payPalOrder.links[i].href;
                        return;
                    }
                }
            }

            if (result.payPalOrder.status === 'CREATED' ){
                for (const i in result.payPalOrder.links) {
                    if (result.payPalOrder.links[i].rel === 'approve'){
                        /*debugger
                        let captureResult = await PayPalPayment.backendRequest('shopOrderCaptureUrl', {}, {
                            'orderId': result.payPalOrder.id,
                            'paymentId': PayPalPayment.getConfigValue('paymentId')
                        });
                        debugger*/
                        window.location = result.payPalOrder.links[i].href;
                        return;
                    }
                }
            }
            debugger
            return result.payPalOrder.id;
        };

        this.captureOrder = async function (data, actions) {
            debugger
            //if we managed to get at this stage, closing the overlay not suppose to be watched anymore
            PayPalPayment.reactOnPayPalOverlayClosed = false;
            let result = await PayPalPayment.backendRequest('shopOrderCaptureUrl', {}, {
                'orderId': data.orderID,
                'paymentId': PayPalPayment.getConfigValue('paymentId'),
                'vaultPayment': PayPalPayment.currentOrder.vaultPayment,
            });

            if (result.status === 'error' ){
                PayPalPayment.showErrorMessage(result.message);
                PayPalPayment.handleError(result.message);
            }

            if (result.status === 'success') {
                PayPalPayment.afterCaptureOrder();
            }
        };

        this.afterCaptureOrder = function (details) {
            window.location = PayPalPayment.getConfigValue('shopThankYouPageUrl');
        };

        this.isCardFieldInvalid = function (name)
        {
            let valid = PayPalPayment.cardFieldsState.fields[name].isValid;
            return false === valid || null === valid ;
        };

        this.validateCardFields = function () {
            this.removeErrorMessage(); //clear all errors

            if (PayPalPayment.isCardFieldInvalid('cardNumberField')) {
                this.showErrorMessage(PayPalI18n.OSC_PAYPAL_ACDC_ERROR_MISSING_NUMBER,
                    'cardNumberError');
                return false;
            } else {
                this.removeErrorMessage('cardNumberError');
            }

            if (PayPalPayment.isCardFieldInvalid('cardExpiryField')) {
                this.showErrorMessage(PayPalI18n.OSC_PAYPAL_ACDC_ERROR_MISSING_EXDATE,
                    'cardExpiryError');
                return false;
            } else {
                this.removeErrorMessage('cardExpiryError');
            }

            if (PayPalPayment.isCardFieldInvalid('cardCvvField')) {
                this.showErrorMessage(PayPalI18n.OSC_PAYPAL_ACDC_ERROR_MISSING_CVV,
                    'cardCvvError');
                return false;
            } else {
                this.removeErrorMessage('cardCvvError');
            }

            if (PayPalPayment.isCardFieldInvalid('cardNameField')) {
                this.showErrorMessage(PayPalI18n.OSC_PAYPAL_ACDC_ERROR_MISSING_NAME,
                    'cardNameError');
                return false;
            } else {
                this.removeErrorMessage('cardNameError');
            }

            return true;
        };

        this.handlePaymentAuthorization = async function (details) {
            const result = await PayPalPayment.authorizeOrder({});
//@TODO figure out how to handle overlay with intent authorize
//PayPalPayment.reactOnPayPalOverlayClosed = false;
            if (result.status === 'error' ){
                PayPalPayment.showErrorMessage(result.message);
                PayPalPayment.handleError(result.message);
            }

            if (result.status === 'success' && result.paymentStatus === 'success'){
                let result = await PayPalPayment.backendRequest('shopOrderCompleteUrl', {}, {
                    'orderId': PayPalPayment.currentOrder.shop.shopOrderId
                });
                if ('success' !== result.status) {
                    return false; //some better err handlig here should be added
                }

                window.location = PayPalPayment.getConfigValue('shopThankYouPageUrl');
                return;
            }
        };

        this.renderCardFields = function () {
            this.initializeAcceptPaymentButton();

            if (null !== this.config.vaultedPaymentSource) {
                return;
            }

            if (!paypal.CardFields) {
                console.error('Card Fields not available in this version of PayPal SDK');
                return;
            }

            const cardFieldsSettings = {
                createOrder: PayPalPayment.createOrder,
                onApprove: PayPalPayment.handlePaymentAuthorization,
                onError: PayPalPayment.handleError,
                onCancel: PayPalPayment.cancelOrder,
                inputEvents: {
                    onChange: (data) => {
                        PayPalPayment.cardFieldsState = data;
                        PayPalPayment.removeSubmitButtonOverlay();
                    }
                }
            };

            if (PayPalPayment.config.captureStrategy === 'CAPTURE') {
                cardFieldsSettings.onApprove = PayPalPayment.captureOrder;
            }

            const cardFields = paypal.CardFields(cardFieldsSettings);

            // Helper-Function to read the calculated CSS properties of an element
            function getComputedStylesAsObject(selector) {
                const element = document.querySelector(selector);
                if (!element) {
                    return {};
                }

                // Get all calculated styles
                const computedStyle = window.getComputedStyle(element);

                // Extract relevant properties and convert them into an object
                const styleObject = {};

                // List of properties you want to adopt
                const relevantProperties = [
                    'color', 'font-size', 'font-family', 'font-weight',
                    'border', 'border-radius', 'padding',
                    'box-shadow', 'height', 'line-height'
                ];

                relevantProperties.forEach(prop => {
                    // CSS properties in JavaScript have camelCase (e.g. fontSize instead of font-size)
                    // But we can leave them in CSS format for the PayPal API
                    styleObject[prop] = computedStyle.getPropertyValue(prop);
                });

                return styleObject;
            }

            if (cardFields.isEligible()) {
                const cardNameContainer = document.getElementById("card-name-field-container");
                const cardNumberContainer = document.getElementById("card-number-field-container");
                const cardCvvContainer = document.getElementById("card-cvv-field-container");
                const cardExpiryContainer = document.getElementById("card-expiry-field-container");
                const submitButton = document.getElementById(
                    PayPalPayment.getConfigValue('buttonSelector').split('#').reverse()[0]
                );

                // Retrieve styles from your existing element
                const formControlStyles = getComputedStylesAsObject('input.form-control');
                // Prepare these styles for PayPal cardFields
                const payPalInputStyles = {
                    'input': formControlStyles
                };

                if (cardNameContainer) {
                    cardFields.NameField({
                        placeholder: PayPalI18n.OSC_PAYPAL_ACDC_CARD_NAME_ON_CARD,
                        style: payPalInputStyles
                    }).render(cardNameContainer);
                }
                if (cardNumberContainer) {
                    cardFields.NumberField({
                        placeholder: PayPalI18n.OSC_PAYPAL_ACDC_CARD_NUMBER,
                        style: payPalInputStyles
                    }).render(cardNumberContainer);
                }
                if (cardCvvContainer) {
                    cardFields.CVVField({
                        placeholder: PayPalI18n.OSC_PAYPAL_ACDC_CARD_CVV,
                        style: payPalInputStyles
                    }).render(cardCvvContainer);
                }
                if (cardExpiryContainer) {
                    cardFields.ExpiryField({
                        placeholder: PayPalI18n.OSC_PAYPAL_ACDC_CARD_EXDATE,
                        style: payPalInputStyles
                    }).render(cardExpiryContainer);
                }
                if (submitButton) {

                    submitButton.addEventListener("click", () => {
                        PayPalPayment.addSubmitButtonOverlay();

                        // Validate fields before submission
                        if (!PayPalPayment.validateCardFields()) {
                            PayPalPayment.removeSubmitButtonOverlay();
                            return;
                        }

                        //enable the PP overlay watcher
                        //PP sdk do not support events, so we have to watch for the overlay
                        PayPalPayment.paypalOverlayWatcher();

                        cardFields.submit().catch(err => {
                            if(null != PayPalPayment.currentError) {
                                PayPalPayment.showErrorMessage(PayPalI18n.OSC_PAYPAL_ACDC_ERROR_INBOX);
                            }

                            PayPalPayment.removeSubmitButtonOverlay();
                        });
                    });
                }
            }
        };

        return this.init();
    };

    document.addEventListener('paypalOverlayClosed', function() {
        //in some cases we shouldn't go forward
        if (true !== PayPalPayment.reactOnPayPalOverlayClosed) {
            return;
        }
        PayPalPayment.cancelOrder().then((e) => {
            PayPalPayment.removeSubmitButtonOverlay();
        });
    });

    window.addEventListener('load', function () {
        if (typeof PayPalPaymentControllerConfig === 'object') {
            if (PayPalPaymentControllerConfig.paymentId !== 'oscpaypal_acdc') {
                return;
            }

            window.PayPalPayment = new PayPalACDCPaymentController();
            window.PayPalPayment.renderCardFields();
        }
    });
})();

(function () {
    let GooglePayPaymentController = function (config) {
        // Inherit from base controller`
        PayPalPaymentControllerBase.call(this, config);

        this.paymentsClient = null;
        this.baseRequest = {
            apiVersion: 2,
            apiVersionMinor: 0,
        };

        /**
         *  Configure support for the Google Pay API
         */
        this.getGooglePaymentDataRequest = async function () {
            const paymentDataRequest = Object.assign({}, PayPalPayment.baseRequest);
            const {allowedPaymentMethods, merchantInfo} = await this.getGooglePayConfig();

            paymentDataRequest.transactionInfo = PayPalPayment.getGoogleTransactionInfo();
            paymentDataRequest.allowedPaymentMethods = allowedPaymentMethods;
            paymentDataRequest.merchantInfo = merchantInfo;
            paymentDataRequest.callbackIntents = ["PAYMENT_AUTHORIZATION"];
            paymentDataRequest.emailRequired = true;
            paymentDataRequest.shippingAddressRequired = PayPalPayment.getConfigValue('useGooglePayAddress');
            paymentDataRequest.shippingAddressParameters = {'phoneNumberRequired': true};

            return paymentDataRequest;
        };

        this.getGoogleTransactionInfo = function () {
            return {
                currencyCode: PayPalPayment.getConfigValue('currency'),
                totalPriceStatus: "FINAL",
                totalPrice: PayPalPayment.getConfigValue('totalPrice'),
                totalPriceLabel: "Total",
            };
        };

        this.getGooglePaymentsClient = function () {
            if (PayPalPayment.paymentsClient === null) {
                PayPalPayment.paymentsClient = new google.payments.api.PaymentsClient({
                    environment: PayPalPayment.getConfigValue('isSandbox') ? "TEST" : "PRODUCTION",
                    paymentDataCallbacks: {
                        onPaymentAuthorized: PayPalPayment.onPaymentAuthorized,
                    },
                });
            }
            return PayPalPayment.paymentsClient;
        };

        this.onGooglePaymentButtonClicked = async function () {
            PayPalPayment.removeErrorMessage();
            PayPalPayment.addSubmitButtonOverlay();
            PayPalPayment.reactOnPayPalOverlayClosed = true;
            let response = await fetch(PayPalPayment.getConfigValue('shopOrderCreateUrl'), {
                method: 'post',
                headers: Object.assign({
                    'content-type': 'application/json',
                }, {}),
                body: JSON.stringify({
                    'deliveryAddressId': PayPalPayment.getConfigValue('deliveryAddressId')
                })
            });

            const result = await response.json();
            if (result.status === 'success') {
                document.dispatchEvent(new CustomEvent('shopOrderCreated', new Object({detail: {...result}})));
            }

            const paymentsClient = PayPalPayment.getGooglePaymentsClient();
            const paymentDataRequest = await PayPalPayment.getGooglePaymentDataRequest();
            paymentDataRequest.transactionInfo = PayPalPayment.getGoogleTransactionInfo();
            if ('function' === typeof paymentsClient.loadPaymentData) {
                try {
                    await paymentsClient.loadPaymentData(paymentDataRequest);
                } catch (err) {
                    // user cancels code
                    if (err.code === 20 ) {
                        await PayPalPayment.cancelOrder();
                    }
                }
            }
        };

        /**
         *  Fetch Default Config from PayPal via PayPal SDK
         *  */
        this.getGooglePayConfig = async function () {
            if (this.config.allowedPaymentMethods == null || this.config.merchantInfo == null) {
                const googlePayConfig = await paypal.Googlepay().config();
                this.config.allowedPaymentMethods = googlePayConfig.allowedPaymentMethods;
                this.config.merchantInfo = googlePayConfig.merchantInfo;
                this.config.merchantInfo.merchantName = this.config.merchantName;
            }
            return {
                allowedPaymentMethods: this.config.allowedPaymentMethods,
                merchantInfo: this.config.merchantInfo
            };
        };

        this.onPaymentAuthorized = function (paymentData) {
            return new Promise(function (resolve) {
                PayPalPayment.processPayment(paymentData)
                    .then(function () {
                        resolve({transactionState: "SUCCESS"});
                    })
                    .catch(function () {
                        resolve({transactionState: "ERROR"});
                    });
            });
        };

        this.getGooglePaymentsClient = function() {
            if (this.paymentsClient === null) {
                this.paymentsClient = new google.payments.api.PaymentsClient({
                    environment: PayPalPayment.getConfigValue('isSandbox') ? "TEST" : "PRODUCTION",
                    paymentDataCallbacks: {
                        onPaymentAuthorized: this.onPaymentAuthorized.bind(this),
                    },
                });
            }
            return this.paymentsClient;
        };

        this.getGoogleIsReadyToPayRequest = function (allowedPaymentMethods) {
            return Object.assign({}, this.baseRequest, {
                allowedPaymentMethods: allowedPaymentMethods
            });
        };

        this.onShopOrderCreated = function (data) {
            PayPalPayment.setShopOrderData(data.detail, 'shop');
        };

        this.onInit = async function (e) {
            let this_ = e.detail;
            await window.googlePayReady;

            const paymentsClient = PayPalPayment.getGooglePaymentsClient();
            const {allowedPaymentMethods} = await PayPalPayment.getGooglePayConfig();
            paymentsClient
                .isReadyToPay(PayPalPayment.getGoogleIsReadyToPayRequest(allowedPaymentMethods))
                .then(function (response) {
                    if (response.result) {
                        const loadingContainerSelector = PayPalPayment.getConfigValue('loadingContainer');
                        const loading = document.querySelector('.' + loadingContainerSelector);
                        if (loading){
                            loading.style.display = 'none';
                        }

                        PayPalPayment.renderButton();
                    }
                })
                .catch(function (err) {
                    console.error(err);
                });
        };

        this.renderButton = function (e) {
            const paymentsClient = PayPalPayment.getGooglePaymentsClient();
            const button = paymentsClient.createButton({
                buttonType: 'buy',
                buttonLocale: this.language,
                onClick: PayPalPayment.onGooglePaymentButtonClicked,
            });
            document.getElementById("oscpaypal_googlepay").appendChild(button);
        };

        this.processPayment = async function (paymentDataAttr) {
            try {
                const createOrderUrl = PayPalPayment.getConfigValue('googlePayOrderCreateUrl');
                const paymentData = {
                    ...paymentDataAttr,
                    shopOrderId: PayPalPayment.currentOrder.shop.shopOrderId
                };

                const {id: orderId, status} = await fetch(createOrderUrl, {
                    method: "POST",
                    headers: {"Content-Type": "application/json"},
                    body: JSON.stringify(paymentData),
                }).then((res) => res.json());

                if (status === "CREATED") {
                    /* Capture the Order */
                    PayPalPayment.confirmOrder(orderId, paymentData);
                    return {transactionState: "SUCCESS"};
                } else if (status === "APPROVED") {
                    /* Capture the Order */
                    PayPalPayment.captureOrder(orderId);
                    return {transactionState: "SUCCESS"};
                } else {
                    PayPalPayment.showErrorMessage(PayPalI18n.OSC_PAYPAL_AUTHORIZATION_DENIED_ERROR);
                    PayPalPayment.handleError();
                    return {transactionState: "ERROR"};
                }
            } catch (err) {
                return {
                    transactionState: "ERROR",
                    error: {
                        message: err.message,
                    },
                };
            }
        };
        this.confirmOrder= async function (orderId, paymentData) {
            await new Promise(resolve => setTimeout(resolve, 1000));
            confirmOrderResponse = await paypal.Googlepay().confirmOrder({
                orderId: orderId,
                paymentMethodData: paymentData.paymentMethodData
            }).catch(function (PayPalGooglePayError) {
                PayPalPayment.handleError(PayPalGooglePayError);
                return;
            });

            if (confirmOrderResponse.status === "PAYER_ACTION_REQUIRED" || confirmOrderResponse.status === 'APPROVED') {
                PayPalPayment.googlePayUserActionRequired(orderId);
            } else {
                PayPalPayment.handleError();
            }
        };

        this.googlePayUserActionRequired = function (orderId) {
            paypal
                .Googlepay()
                .initiatePayerAction({ orderId: orderId })
                .then(async () => {
                    await PayPalPayment.executeOxidOrder(orderId);
                    await PayPalPayment.captureOrder(orderId);
                });
        };

        this.executeOxidOrder = async function (orderId) {
            const url = PayPalPayment.getConfigValue('executeGooglePayOrder');
            createData = new FormData();
            createData.append('orderID', orderId);

            try {
                const res = await fetch(url, {
                    method: 'POST',
                    body: createData
                });
                const data = await res.json();

                if (data.status === "ERROR") {
                    location.reload();
                }

                return data;
            } catch (error) {
                PayPalPayment.handleError();
                throw error; // Forward the error so that the calling method can react
            }
        };

        this.captureOrder = async function (orderId) {
            const url = PayPalPayment.getConfigValue('captureGooglePayOrder');
            captureData = new FormData();
            captureData.append('orderID', orderId);
            await fetch(url, {
                method: 'post',
                body: captureData
            }).then(function (res) {
                return res.json();
            }).then(function (data) {
                if ('undefined' !== typeof data.token) {
                    window.location = PayPalPayment.getConfigValue('finalizeGooglePayOrder') + '&token=' + data.token;
                    return;
                }

                if (data.status === "ERROR") {
                    PayPalPayment.handleError();
                }
            }).catch(reason => {
                PayPalPayment.handleError();
            });
        };

        document.addEventListener('PayPalPaymentControllerInitialized', this.onInit);
        document.addEventListener('shopOrderCreated', this.onShopOrderCreated);

        return this.init();
    };

    window.addEventListener('load', function() {
        if (typeof PayPalPaymentControllerConfig === 'object' &&
            PayPalPaymentControllerConfig.paymentId === 'oscpaypal_googlepay') {
            window.PayPalPayment = new GooglePayPaymentController();
        }
    });
})();

(function(){
    window.addEventListener('popstate', async function (e) {
        if (true === window.PayPalExpressSession.started) {
            window.PayPalExpressSession.started = false;
            await window.PayPalExpressSession.cancelPayPalExpressSession();
            window.history.back(); //real back 1 step
        }
    });
})();

